      BR: ['https://www2.camara.leg.br/legin/fed/lei/1940-1949/lei-662-6-abril-1949-347136-norma-pl.html', 'https://www.camara.leg.br/proposicoesWeb/prop_mostrarintegra?codteor=1518158'],
